@php
/**
 * Master Kop Surat Demosi Jabatan - HRIS Temprina
 * Dinamis mengambil dari data tabel m_media (mengutamakan upload terbaru Kop / Demosi)
 * Sesuai crop presisi dari PDF acuan resmi Demosi Jabatan Temprina
 */
$demosiKopSrc = '';

try {
    $kopMediaDemosi = \DB::table('m_media')
        ->select('m_media.*')
        ->leftJoin('m_general', 'm_general.id', '=', 'm_media.kategori_id')
        ->where(function($q) {
            $q->where('m_media.is_active', true)
              ->orWhereNull('m_media.is_active');
        })
        ->where(function($q) {
            $q->where(function($sub) {
                $sub->whereIn(\DB::raw("UPPER(TRIM(COALESCE(m_media.kode, '')))"), [
                    'KOP-DEMOSI', 'HEADER-DEMOSI', 'KOP_DEMOSI', 'HEADER_DEMOSI', 'LOGO-DEMOSI', 'LOGO-KOP-DEMOSI'
                ])
                ->orWhereRaw("UPPER(TRIM(COALESCE(m_media.kode, ''))) LIKE '%DEMOSI%'")
                ->orWhereRaw("UPPER(TRIM(COALESCE(m_media.nama, ''))) LIKE '%DEMOSI%'")
                ->orWhereRaw("UPPER(TRIM(COALESCE(m_general.value, ''))) LIKE '%DEMOSI%'");
            })
            ->whereRaw("UPPER(COALESCE(m_media.kode,'')) NOT LIKE '%PKWT%'")
            ->whereRaw("UPPER(COALESCE(m_media.nama,'')) NOT LIKE '%PKWT%'")
            ->whereRaw("UPPER(COALESCE(m_media.kode,'')) NOT LIKE '%FOOTER%'")
            ->whereRaw("UPPER(COALESCE(m_media.nama,'')) NOT LIKE '%FOOTER%'")
            ->whereRaw("UPPER(COALESCE(m_media.kode,'')) NOT LIKE '%DIM%'");
        })
        ->orderByRaw("CASE 
            WHEN UPPER(COALESCE(m_media.kode,'')) IN ('KOP-DEMOSI', 'KOP_DEMOSI', 'HEADER-DEMOSI') THEN 0
            WHEN UPPER(COALESCE(m_media.kode,'')) LIKE '%DEMOSI%' AND (UPPER(COALESCE(m_media.kode,'')) LIKE '%KOP%' OR UPPER(COALESCE(m_media.kode,'')) LIKE '%HEADER%') THEN 1
            WHEN UPPER(COALESCE(m_media.nama,'')) LIKE '%DEMOSI%' AND (UPPER(COALESCE(m_media.nama,'')) LIKE '%KOP%' OR UPPER(COALESCE(m_media.nama,'')) LIKE '%HEADER%') THEN 2
            WHEN UPPER(COALESCE(m_media.kode,'')) LIKE '%DEMOSI%' THEN 3
            WHEN UPPER(COALESCE(m_media.nama,'')) LIKE '%DEMOSI%' THEN 4
            ELSE 5
        END")
        ->orderBy('m_media.id', 'desc')
        ->first();

    if ($kopMediaDemosi && !empty($kopMediaDemosi->file_path)) {
        $rawPath = trim($kopMediaDemosi->file_path);
        if (str_starts_with($rawPath, 'data:image')) {
            $demosiKopSrc = $rawPath;
        } else {
            $clean = preg_replace('#^https?://[^/]+/#i', '', ltrim($rawPath, '/'));
            $clean = ltrim($clean, '/');
            $basename = basename($clean);

            $pathCandidates = array_unique(array_filter([
                $clean,
                $basename,
                str_contains($clean, ':::') ? explode(':::', $clean)[0] : null,
                str_contains($basename, ':::') ? explode(':::', $basename)[0] : null,
                str_contains($clean, ':::') ? (explode(':::', $clean)[1] ?? null) : null,
                str_contains($basename, ':::') ? (explode(':::', $basename)[1] ?? null) : null,
            ]));

            $subPaths = [];
            foreach ($pathCandidates as $cand) {
                $cand = trim($cand);
                if (empty($cand)) continue;
                $candBase = basename($cand);
                $subPaths[] = $cand;
                $subPaths[] = $candBase;
                $subPaths[] = 'uploads/m_media/' . $candBase;
                $subPaths[] = 'uploads/' . $candBase;
                $subPaths[] = 'storage/uploads/m_media/' . $candBase;
                $subPaths[] = 'storage/' . $candBase;
                $subPaths[] = 'images/' . $candBase;
                $subPaths[] = 'media/' . $candBase;
                $subPaths[] = 'uploads/m_media/' . $cand;
                $subPaths[] = 'storage/' . $cand;
            }
            $subPaths = array_unique(array_filter($subPaths));

            foreach ($subPaths as $sub) {
                $pathsToCheck = [];
                if (function_exists('public_path')) {
                    $pathsToCheck[] = public_path($sub);
                    $pathsToCheck[] = public_path('storage/' . $sub);
                }
                if (function_exists('storage_path')) {
                    $pathsToCheck[] = storage_path('app/public/' . $sub);
                    $pathsToCheck[] = storage_path('app/' . $sub);
                    $pathsToCheck[] = storage_path($sub);
                }
                if (function_exists('base_path')) {
                    $pathsToCheck[] = base_path('storage/app/public/' . $sub);
                    $pathsToCheck[] = base_path('public/' . $sub);
                    $pathsToCheck[] = base_path('public/storage/' . $sub);
                    $pathsToCheck[] = base_path($sub);
                }
                $pathsToCheck[] = '/opt/www/hris/storage/app/public/' . $sub;
                $pathsToCheck[] = '/opt/www/hris/public/' . $sub;
                $pathsToCheck[] = '/var/www/html/storage/app/public/' . $sub;
                $pathsToCheck[] = '/var/www/html/public/' . $sub;
                $pathsToCheck[] = '/var/www/hris/storage/app/public/' . $sub;
                $pathsToCheck[] = '/var/www/hris/public/' . $sub;

                foreach ($pathsToCheck as $full) {
                    if ($full && file_exists($full) && is_file($full) && filesize($full) > 50) {
                        $ext = strtolower(pathinfo($full, PATHINFO_EXTENSION));
                        $mime = match($ext) {
                            'png' => 'image/png',
                            'gif' => 'image/gif',
                            'webp' => 'image/webp',
                            'svg' => 'image/svg+xml',
                            default => 'image/jpeg'
                        };
                        $demosiKopSrc = 'data:' . $mime . ';base64,' . base64_encode(file_get_contents($full));
                        break 2;
                    }
                }
            }

            if (empty($demosiKopSrc) && function_exists('file_get_contents')) {
                $streamCtx = stream_context_create([
                    'http' => ['timeout' => 2, 'ignore_errors' => true],
                    'ssl'  => ['verify_peer' => false, 'verify_peer_name' => false]
                ]);
                $urlsToTry = [];
                if (str_starts_with($rawPath, 'http://') || str_starts_with($rawPath, 'https://')) {
                    $urlsToTry[] = $rawPath;
                }
                foreach ($pathCandidates as $cand) {
                    $candBase = basename($cand);
                    $urlsToTry[] = 'https://hris.temprina.com/storage/uploads/m_media/' . $candBase;
                    $urlsToTry[] = 'https://hris.temprina.com/storage/uploads/m_media/' . rawurlencode($candBase);
                    $urlsToTry[] = 'https://hris.temprina.com/uploads/m_media/' . rawurlencode($candBase);
                    $urlsToTry[] = 'https://hris.temprina.com/storage/' . $candBase;
                    $urlsToTry[] = 'https://hris.temprina.com/' . ltrim($cand, '/');
                    $urlsToTry[] = 'http://127.0.0.1/storage/uploads/m_media/' . $candBase;
                    $urlsToTry[] = 'http://localhost/storage/uploads/m_media/' . $candBase;
                }

                foreach (array_unique(array_filter($urlsToTry)) as $u) {
                    try {
                        $remoteData = @file_get_contents($u, false, $streamCtx);
                        if ($remoteData && strlen($remoteData) > 50) {
                            $mime = 'image/jpeg';
                            if (str_starts_with($remoteData, "\x89PNG")) {
                                $mime = 'image/png';
                            } elseif (str_starts_with($remoteData, "GIF")) {
                                $mime = 'image/gif';
                            }
                            $demosiKopSrc = 'data:' . $mime . ';base64,' . base64_encode($remoteData);
                            break;
                        }
                    } catch (\Throwable $e) {}
                }
            }
        }
    }
} catch (\Throwable $th) {
    // Silently continue to local fallback
}

// Fallback 1: File lokal di folder media/
if (empty($demosiKopSrc)) {
    $localFiles = [
        function_exists('base_path') ? base_path('media/header_sk_demosi_opt.jpg') : '',
        function_exists('base_path') ? base_path('media/header_sk_demosi.jpg') : '',
        function_exists('base_path') ? base_path('media/header_sk_demosi.png') : '',
    ];
    foreach ($localFiles as $lf) {
        if ($lf && file_exists($lf) && is_file($lf) && filesize($lf) > 50) {
            $ext = strtolower(pathinfo($lf, PATHINFO_EXTENSION));
            $mime = ($ext === 'png') ? 'image/png' : 'image/jpeg';
            $demosiKopSrc = 'data:' . $mime . ';base64,' . base64_encode(file_get_contents($lf));
            break;
        }
    }
}

// Fallback 2: File teks base64 lokal
if (empty($demosiKopSrc)) {
    $b64TxtPath = function_exists('base_path') ? base_path('media/real_header_demosi_b64.txt') : '';
    if ($b64TxtPath && file_exists($b64TxtPath)) {
        $demosiKopSrc = 'data:image/jpeg;base64,' . trim(file_get_contents($b64TxtPath));
    }
}

// Fallback 3: Base64 default ter-embed langsung (100% aman jika file/database belum tersinkron)
if (empty($demosiKopSrc)) {
    $demosiKopSrc = 'data:image/jpeg;base64,' . '';
}
@endphp

<!-- RENDER KOP SURAT DEMOSI JABATAN (PERSIS PDF ACUAN RESMI TEMPRINA) -->
<table width="100%" cellpadding="0" cellspacing="0" style="width:100%; border-collapse:collapse; margin-bottom:12px; padding:0;">
  <tr>
    <td align="center" style="width:100%; text-align:center; padding:0; vertical-align:middle;">
      <img src="{{ $demosiKopSrc }}" width="700" style="width:700px; max-width:100%;" alt="Kop Surat Temprina Media Grafika">
    </td>
  </tr>
</table>
